{"file_text": "@page "/settings"
@using sv_3e0d97e442ba46538a33d242be57f1ee.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (_profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                <img src="@_editProfile.AvatarUrl" alt="Avatar" />
                            </div>
                            <label>Avatar URL</label>
                            <input type="text" @bind="_editProfile.AvatarUrl" />
                        </div>
                        <div class="profile-fields">
                            <div class="form-group">
                                <label>Display Name</label>
                                <input type="text" @bind="_editProfile.DisplayName" />
                            </div>
                            <div class="form-group">
                                <label>Email</label>
                                <input type="email" @bind="_editProfile.Email" />
                            </div>
                            <div class="form-group">
                                <label>Bio</label>
                                <textarea rows="4" @bind="_editProfile.Bio"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (_notifPrefs is not null)
                {
                    <div class="toggle-group">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <input type="checkbox" @bind="_editNotifEmailEnabled" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <input type="checkbox" @bind="_editNotifPushEnabled" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <input type="checkbox" @bind="_editNotifWeeklyDigest" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channels-list">
                        @foreach (var channel in _allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@_editMutedChannels.Contains(channel)"
                                       @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (_security is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                            <span>Change Password</span>
                            <span class="expand-icon">@(_passwordPanelOpen ? "▼" : "▶")</span>
                        </button>
                        @if (_passwordPanelOpen)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label>Current Password</label>
                                    <input type="password" @bind="_currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label>New Password</label>
                                    <input type="password" @bind="_newPassword" />
                                </div>
                                <div class="form-group">
                                    <label>Confirm Password</label>
                                    <input type="password" @bind="_confirmPassword" />
                                </div>
                                <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group" style="margin-top:1.5rem;">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Two-Factor Authentication</span>
                                <input type="checkbox" @bind="_twoFactorEnabled" />
                                <span class="toggle-switch"></span>
                            </label>
                            <span class="status-indicator @(_twoFactorEnabled ? "status-active" : "status-inactive")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </div>
                    </div>

                    @if (_security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _security.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (_showRevokeConfirm && _sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Revoke Session</h3>
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (_appearance is not null)
                {
                    <div class="form-group">
                        <label><strong>Theme</strong></label>
                        <div class="radio-group">
                            <label><input type="radio" name="theme" value="Light" checked="@(_editTheme == "Light")" @onchange='() => _editTheme = "Light"' /> Light</label>
                            <label><input type="radio" name="theme" value="Dark" checked="@(_editTheme == "Dark")" @onchange='() => _editTheme = "Dark"' /> Dark</label>
                            <label><input type="radio" name="theme" value="System" checked="@(_editTheme == "System")" @onchange='() => _editTheme = "System"' /> System</label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label><strong>Font Size</strong></label>
                        <div class="radio-group">
                            <label><input type="radio" name="fontSize" value="Small" checked="@(_editFontSize == "Small")" @onchange='() => _editFontSize = "Small"' /> Small</label>
                            <label><input type="radio" name="fontSize" value="Medium" checked="@(_editFontSize == "Medium")" @onchange='() => _editFontSize = "Medium"' /> Medium</label>
                            <label><input type="radio" name="fontSize" value="Large" checked="@(_editFontSize == "Large")" @onchange='() => _editFontSize = "Large"' /> Large</label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label><strong>Language</strong></label>
                        <select @bind="_editLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <input type="checkbox" @bind="_editCompactMode" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">Preview Area</div>
                        <p class="preview-text">This is how your content will look with the selected settings.</p>
                        <div class="preview-card">
                            <strong>Sample Card</strong>
                            <p>Theme: @_editTheme | Font: @_editFontSize | Lang: @_editLanguage</p>
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "toast-success";

    // Profile
    private UserProfile? _profile;
    private ProfileEdit _editProfile = new();

    // Notifications
    private NotificationPrefs? _notifPrefs;
    private bool _editNotifEmailEnabled;
    private bool _editNotifPushEnabled;
    private bool _editNotifWeeklyDigest;
    private List<string> _editMutedChannels = [];
    private readonly List<string> _allChannels = ["general", "announcements", "marketing", "engineering", "design", "support"];

    // Security
    private SecuritySettings? _security;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile methods
    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        ResetProfileEdit();
    }

    private void ResetProfileEdit()
    {
        if (_profile is null) return;
        _editProfile = new ProfileEdit
        {
            DisplayName = _profile.DisplayName,
            Email = _profile.Email,
            AvatarUrl = _profile.AvatarUrl,
            Bio = _profile.Bio
        };
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "toast-success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileEdit();
        ShowToast("Changes discarded.", "toast-info");
    }

    // Notification methods
    private async Task LoadNotifications()
    {
        _notifPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifEmailEnabled = _notifPrefs.EmailNotifications;
        _editNotifPushEnabled = _notifPrefs.PushNotifications;
        _editNotifWeeklyDigest = _notifPrefs.WeeklyDigest;
        _editMutedChannels = new List<string>(_notifPrefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editMutedChannels.Contains(channel))
            _editMutedChannels.Add(channel);
        else if (!muted)
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_editNotifEmailEnabled, _editNotifPushEnabled, _editNotifWeeklyDigest, new List<string>(_editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notifPrefs = prefs;
        ShowToast("Notification preferences saved!", "toast-success");
    }

    // Security methods
    private async Task LoadSecurity()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _security.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", "toast-error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        await LoadSecurity();
        ShowToast("Password updated successfully!", "toast-success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
        await LoadSecurity();
        ShowToast("Session revoked.", "toast-success");
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editTheme = _appearance.Theme;
        _editFontSize = _appearance.FontSize;
        _editLanguage = _appearance.Language;
        _editCompactMode = _appearance.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
        ShowToast("Appearance settings saved!", "toast-success");
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_editTheme.ToLower()} preview-font-{_editFontSize.ToLower()}";
        if (_editCompactMode) classes += " preview-compact";
        return classes;
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        ToastMessage = message;
        ToastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => ToastMessage = null;

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}
